// Dane z formularza i odpowiedź AI
const zgloszenie = $('On form submission').item.json;
let ai = $json.output?.[0]?.content?.[0]?.text;

// Gdyby AI zwróciło tekst zamiast danych, próbujemy go odczytać
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (e) { ai = null; }
}

const kategorie = ['dostęp', 'sprzęt', 'oprogramowanie', 'inne'];
const problemy = [];

if (!ai || typeof ai !== 'object') {
  problemy.push('AI nie zwróciło poprawnego JSON-a');
} else {
  if (!kategorie.includes(ai.kategoria)) problemy.push('nieznana kategoria: ' + ai.kategoria);
  if (![1, 2, 3].includes(ai.pilnosc)) problemy.push('zła pilność: ' + ai.pilnosc);
  if (!ai.streszczenie) problemy.push('brak streszczenia');
  if (typeof ai.pewnosc !== 'number') problemy.push('brak pewności');
  else if (ai.pewnosc < 60) problemy.push('niska pewność: ' + ai.pewnosc);
}

return {
  json: {
    imie: zgloszenie['Imię:'],
    email: zgloszenie['E-mail:'],
    opis: zgloszenie['Opis problemu:'],
    kategoria: ai?.kategoria ?? 'inne',
    pilnosc: ai?.pilnosc ?? 2,
    streszczenie: ai?.streszczenie ?? '',
    pewnosc: ai?.pewnosc ?? 0,
    doSprawdzenia: problemy.length > 0,
    problemy: problemy.join('; '),
    data: zgloszenie.submittedAt
  }
};
